for(const key of ['w','h'])$('page-'+key).onchange=()=>{const v=Number($('page-'+key).value);if(v<1||v>5000||!Number.isFinite(v))return;checkpoint();syncPage();current()[key]=v;current().trim=null;loadPage();commit('Размер страницы изменён; объекты сохранили свой размер');};
for(const key of ['x','y','w','h'])$('obj-'+key).onchange=()=>{const b=selectedBox(),v=Number($('obj-'+key).value);if(!b||!Number.isFinite(v))return;checkpoint();if(key==='x'||key==='y')for(const el of editable())move(el,key==='x'?v-b.x:0,key==='y'?v-b.y:0);else{if(v<=0)return;let w=key==='w'?v:b.width,h=key==='h'?v:b.height;if($('proportions').checked){if(key==='w')h=b.height*v/b.width;else w=b.width*v/b.height;}rescale(b,w,h);}commit();};
